#!/bin/bash
set -euo pipefail
umask 077
task=/root/sezika-experiments/20261009-repaired-training-8192
test "$(hostname)" = digisyn-gpu01
test "$(timeout 2s cat "$task/task-identity")" = sezika-token-limit-20261009-8192
test "$(timeout 2s cat /proc/sys/kernel/random/boot_id)" = 31951b0f-232d-40c2-aec0-d7e7dd5215a6
test ! -e "$task/cancel.request" && test ! -L "$task/stage.lock"
exec {lockfd}> "$task/stage.lock"
flock -n "$lockfd" || exit 73
run=$task/.artifacts/stage-postreboot-diagnosis
test ! -e "$run" && test ! -L "$run"
mkdir "$run"
printf '%s' '' | base64 --decode > "$run/diagnose.sh"
printf '%s  %s\n' '2c578e2e905917b3988051a550bc9a1dc6162de0d8d1eddfae69b97a9f3f0e62' "$run/diagnose.sh" | timeout 2s sha256sum -c --quiet -
timeout 2s bash -n "$run/diagnose.sh"
set +e
timeout --signal=TERM --kill-after=3s 72s bash "$task/remote/Invoke-BoundedLinux.sh" "$run" 60 8 0 file none -- /bin/bash "$run/diagnose.sh"
rc=$?
set -e
printf 'diagnosis_linux_runner_exit=%s\n' "$rc"
timeout 2s cat "$run/result.tsv"
timeout 2s cat "$run/payload.stdout.log" "$run/payload.stderr.log"
exit "$rc"